import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.45.0";
import { resolveSigningSecret, verifyHmacSignature } from "../_shared/barcode-scan-ingest/hmac.ts";
import {
  createSupabaseBarcodeScanIngestDb,
  processBarcodeScanIngest,
  resolveIngestHttpStatus,
  validateIngestHeaders,
} from "../_shared/barcode-scan-ingest/ingest.ts";
import type { BarcodeScanIngestResponse } from "../_shared/barcode-scan-ingest/types.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type, x-source-app, x-idempotency-key, x-oasis-signature",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

function jsonResponse(body: BarcodeScanIngestResponse | Record<string, unknown>, status: number): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}

serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { status: 200, headers: corsHeaders });
  }

  if (req.method !== "POST") {
    return jsonResponse({ ok: false, reason: "method_not_allowed", message: "POST required" }, 405);
  }

  const rawBody = await req.text();
  const headers = {
    sourceApp: req.headers.get("X-Source-App") ?? "",
    idempotencyKey: req.headers.get("X-Idempotency-Key") ?? "",
    signature: req.headers.get("X-Oasis-Signature") ?? "",
  };

  const headerError = validateIngestHeaders(headers);
  if (headerError) {
    return jsonResponse(headerError, resolveIngestHttpStatus(headerError.reason));
  }

  const secret = resolveSigningSecret({
    BARCODE_APP_SCAN_SIGNING_SECRET: Deno.env.get("BARCODE_APP_SCAN_SIGNING_SECRET") ?? undefined,
    CENTRAL_SCAN_SIGNING_SECRET: Deno.env.get("CENTRAL_SCAN_SIGNING_SECRET") ?? undefined,
  });

  const hmac = await verifyHmacSignature({
    body: rawBody,
    idempotencyKey: headers.idempotencyKey,
    signatureHeader: headers.signature,
    secret,
  });

  if (!hmac.ok) {
    const reason = hmac.reason ?? "signature_invalid";
    const message =
      reason === "signing_secret_missing"
        ? "Server signing secret is not configured"
        : reason === "signature_missing"
          ? "X-Oasis-Signature is required"
          : reason === "missing_idempotency_key"
            ? "X-Idempotency-Key is required"
            : "Invalid HMAC signature";
    return jsonResponse({ ok: false, reason, message }, resolveIngestHttpStatus(reason));
  }

  let payload: unknown;
  try {
    payload = rawBody ? JSON.parse(rawBody) : null;
  } catch {
    return jsonResponse({ ok: false, reason: "invalid_json", message: "Request body must be valid JSON" }, 400);
  }

  const supabase = createClient(
    Deno.env.get("SUPABASE_URL")!,
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!,
    { auth: { persistSession: false } },
  );

  try {
    const result = await processBarcodeScanIngest({
      headers,
      payload,
      idempotencyKey: headers.idempotencyKey.trim(),
      submittedAt: new Date().toISOString(),
      db: createSupabaseBarcodeScanIngestDb(supabase),
    });

    if (!result.ok) {
      return jsonResponse(result, resolveIngestHttpStatus(result.reason));
    }

    return jsonResponse(result, 200);
  } catch (err) {
    console.error("[barcode-scan-ingest] unexpected error:", err);
    return jsonResponse(
      { ok: false, reason: "internal_error", message: "Unable to record scan" },
      500,
    );
  }
});

/** HMAC-SHA256 verification for Barcode App scan ingest requests. */

const encoder = new TextEncoder();

export function resolveSigningSecret(env: {
  BARCODE_APP_SCAN_SIGNING_SECRET?: string;
  CENTRAL_SCAN_SIGNING_SECRET?: string;
}): string | null {
  const primary = env.BARCODE_APP_SCAN_SIGNING_SECRET?.trim();
  if (primary) return primary;
  const alias = env.CENTRAL_SCAN_SIGNING_SECRET?.trim();
  return alias || null;
}

export function buildBarcodeScanSignedMessage(idempotencyKey: string, body: string): string {
  return `${idempotencyKey.trim()}\n${body}`;
}

export async function computeHmacSha256Hex(message: string, secret: string): Promise<string> {
  const key = await crypto.subtle.importKey(
    "raw",
    encoder.encode(secret),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"],
  );
  const signature = await crypto.subtle.sign("HMAC", key, encoder.encode(message));
  return Array.from(new Uint8Array(signature))
    .map((byte) => byte.toString(16).padStart(2, "0"))
    .join("");
}

export function constantTimeEqual(a: string, b: string): boolean {
  const left = a.trim();
  const right = b.trim();
  if (left.length !== right.length) return false;
  let mismatch = 0;
  for (let i = 0; i < left.length; i++) {
    mismatch |= left.charCodeAt(i) ^ right.charCodeAt(i);
  }
  return mismatch === 0;
}

export function normalizeSignatureHeader(signature: string): string {
  const trimmed = signature.trim();
  const sha256Prefix = /^sha256=/i;
  if (sha256Prefix.test(trimmed)) {
    return trimmed.replace(sha256Prefix, "").trim();
  }
  return trimmed;
}

export interface HmacVerificationResult {
  ok: boolean;
  reason: string | null;
}

export async function verifyHmacSignature(input: {
  body: string;
  idempotencyKey: string;
  signatureHeader: string | null | undefined;
  secret: string | null | undefined;
}): Promise<HmacVerificationResult> {
  if (!input.secret?.trim()) {
    return { ok: false, reason: "signing_secret_missing" };
  }
  if (!input.signatureHeader?.trim()) {
    return { ok: false, reason: "signature_missing" };
  }

  const idempotencyKey = input.idempotencyKey.trim();
  if (!idempotencyKey) {
    return { ok: false, reason: "missing_idempotency_key" };
  }

  const provided = normalizeSignatureHeader(input.signatureHeader);
  const signedMessage = buildBarcodeScanSignedMessage(idempotencyKey, input.body);
  const expected = await computeHmacSha256Hex(signedMessage, input.secret);
  if (!constantTimeEqual(provided.toLowerCase(), expected.toLowerCase())) {
    return { ok: false, reason: "signature_invalid" };
  }
  return { ok: true, reason: null };
}

import { validateCtnSoBarcode } from "./ctnSo.ts";
import {
  BARCODE_INGEST_SCAN_TYPES,
  BARCODE_INGEST_SOURCE_APP,
  BARCODE_INGEST_VERIFICATION_TYPES,
  type BarcodeScanIngestDuplicateResponse,
  type BarcodeScanIngestFailureResponse,
  type BarcodeScanIngestHeaders,
  type BarcodeScanIngestResponse,
  type BarcodeScanIngestSuccessResponse,
  type BarcodeScanPayload,
  SCAN_TYPE_VERIFICATION_MAP,
} from "./types.ts";

export interface IngestOrderRow {
  id: string;
  order_number: string;
}

export interface IngestScanRow {
  id: string;
  idempotency_key: string | null;
}

export interface InsertOperationalScanInput {
  scan_type: string;
  verification_type: string;
  entity_type: string;
  entity_id: string;
  order_id: string;
  barcode_value: string;
  expected_barcode: string;
  verification_status: string;
  scan_source: string;
  actor_role: string;
  metadata: Record<string, unknown>;
  correlation_id: string;
  idempotency_key: string;
}

export interface BarcodeScanIngestDb {
  findOrderById(orderId: string): Promise<IngestOrderRow | null>;
  findScanByIdempotencyKey(key: string): Promise<IngestScanRow | null>;
  insertScan(row: InsertOperationalScanInput): Promise<{ id: string }>;
}

export interface ProcessBarcodeScanIngestInput {
  headers: BarcodeScanIngestHeaders;
  payload: unknown;
  idempotencyKey: string;
  submittedAt: string;
  db: BarcodeScanIngestDb;
}

function failure(reason: string, message: string): BarcodeScanIngestFailureResponse {
  return { ok: false, reason, message };
}

function duplicate(): BarcodeScanIngestDuplicateResponse {
  return {
    ok: true,
    duplicate: true,
    message: "Scan already recorded",
  };
}

function success(scanId: string, reference: string): BarcodeScanIngestSuccessResponse {
  return {
    ok: true,
    scan_id: scanId,
    reference,
    message: "Scan recorded",
  };
}

export function validateIngestHeaders(headers: BarcodeScanIngestHeaders): BarcodeScanIngestFailureResponse | null {
  if (headers.sourceApp.trim().toLowerCase() !== BARCODE_INGEST_SOURCE_APP) {
    return failure("invalid_source_app", "X-Source-App must be barcode_app");
  }
  if (!headers.idempotencyKey.trim()) {
    return failure("missing_idempotency_key", "X-Idempotency-Key is required");
  }
  return null;
}

const INGEST_AUTH_FAILURE_REASONS = new Set([
  "missing_signature",
  "signature_missing",
  "signature_invalid",
  "signing_secret_missing",
]);

/** Maps ingest failure reason codes to HTTP status for the edge handler. */
export function resolveIngestHttpStatus(reason: string): number {
  if (INGEST_AUTH_FAILURE_REASONS.has(reason)) return 401;
  if (reason === "order_not_found") return 404;
  return 400;
}

export function parseBarcodeScanPayload(raw: unknown): BarcodeScanPayload | BarcodeScanIngestFailureResponse {
  if (!raw || typeof raw !== "object") {
    return failure("invalid_payload", "Request body must be a JSON object");
  }
  const body = raw as Record<string, unknown>;
  const requiredStringFields = [
    "source_app",
    "order_id",
    "order_number",
    "scan_type",
    "verification_type",
    "entity_type",
    "barcode_value",
    "expected_barcode",
    "verification_status",
    "scan_source",
  ] as const;

  for (const field of requiredStringFields) {
    if (typeof body[field] !== "string" || !String(body[field]).trim()) {
      return failure("invalid_payload", `${field} is required`);
    }
  }

  return {
    source_app: body.source_app as BarcodeScanPayload["source_app"],
    order_id: String(body.order_id).trim(),
    order_number: String(body.order_number).trim(),
    scan_type: body.scan_type as BarcodeScanPayload["scan_type"],
    verification_type: body.verification_type as BarcodeScanPayload["verification_type"],
    entity_type: "order",
    barcode_value: String(body.barcode_value).trim(),
    expected_barcode: String(body.expected_barcode).trim(),
    verification_status: body.verification_status as BarcodeScanPayload["verification_status"],
    scan_source: String(body.scan_source).trim(),
    barcode_app_reference:
      typeof body.barcode_app_reference === "string" ? body.barcode_app_reference.trim() : undefined,
    submitted_at: typeof body.submitted_at === "string" ? body.submitted_at.trim() : undefined,
  };
}

export function validateBarcodeScanBusinessRules(
  payload: BarcodeScanPayload,
): BarcodeScanIngestFailureResponse | null {
  if (payload.source_app !== BARCODE_INGEST_SOURCE_APP) {
    return failure("invalid_source_app", "source_app must be barcode_app");
  }
  if (payload.verification_status !== "verified") {
    return failure("unverified_payload", "verification_status must be verified");
  }
  if (!payload.order_id.trim()) {
    return failure("missing_order_id", "order_id is required");
  }
  if (!payload.order_number.trim()) {
    return failure("missing_order_number", "order_number is required");
  }
  if (payload.entity_type !== "order") {
    return failure("invalid_entity_type", "entity_type must be order");
  }
  if (!(BARCODE_INGEST_SCAN_TYPES as readonly string[]).includes(payload.scan_type)) {
    return failure("invalid_scan_type", "scan_type must be dispatch_gate or carton");
  }
  if (!(BARCODE_INGEST_VERIFICATION_TYPES as readonly string[]).includes(payload.verification_type)) {
    return failure("invalid_verification_type", "verification_type is invalid for barcode ingest");
  }
  if (SCAN_TYPE_VERIFICATION_MAP[payload.scan_type] !== payload.verification_type) {
    return failure(
      "scan_type_verification_mismatch",
      `scan_type ${payload.scan_type} requires verification_type ${SCAN_TYPE_VERIFICATION_MAP[payload.scan_type]}`,
    );
  }

  const ctn = validateCtnSoBarcode({
    barcodeValue: payload.barcode_value,
    expectedBarcode: payload.expected_barcode,
    orderNumber: payload.order_number,
  });
  if (!ctn.ok) {
    return failure("invalid_barcode", ctn.reason ?? "Invalid CTN-SO barcode");
  }

  return null;
}

export async function processBarcodeScanIngest(
  input: ProcessBarcodeScanIngestInput,
): Promise<BarcodeScanIngestResponse> {
  const headerError = validateIngestHeaders(input.headers);
  if (headerError) return headerError;

  const parsed = parseBarcodeScanPayload(input.payload);
  if (!parsed || (parsed as BarcodeScanIngestFailureResponse).ok === false) {
    return parsed as BarcodeScanIngestFailureResponse;
  }

  const payload = parsed as BarcodeScanPayload;
  const businessError = validateBarcodeScanBusinessRules(payload);
  if (businessError) return businessError;

  const existing = await input.db.findScanByIdempotencyKey(input.idempotencyKey);
  if (existing) {
    return duplicate();
  }

  const order = await input.db.findOrderById(payload.order_id);
  if (!order) {
    return failure("order_not_found", "order_id does not exist");
  }

  const normalizedOrderNumber = payload.order_number.trim().toUpperCase();
  const persistedOrderNumber = order.order_number.trim().toUpperCase();
  if (persistedOrderNumber !== normalizedOrderNumber) {
    return failure("order_number_mismatch", "order_number does not match order");
  }

  const metadata: Record<string, unknown> = {
    source_app: BARCODE_INGEST_SOURCE_APP,
    idempotency_key: input.idempotencyKey,
    submitted_at: payload.submitted_at ?? input.submittedAt,
  };
  if (payload.barcode_app_reference) {
    metadata.barcode_app_reference = payload.barcode_app_reference;
  }

  const insertRow: InsertOperationalScanInput = {
    scan_type: payload.scan_type,
    verification_type: payload.verification_type,
    entity_type: "order",
    entity_id: payload.order_id,
    order_id: payload.order_id,
    barcode_value: payload.barcode_value.trim().toUpperCase(),
    expected_barcode: payload.expected_barcode.trim().toUpperCase(),
    verification_status: "verified",
    scan_source: payload.scan_source,
    actor_role: "barcode_app",
    metadata,
    correlation_id: `barcode-ingest:${input.idempotencyKey}`,
    idempotency_key: input.idempotencyKey,
  };

  const inserted = await input.db.insertScan(insertRow);
  const reference = payload.barcode_app_reference ?? inserted.id;
  return success(inserted.id, reference);
}

export function createSupabaseBarcodeScanIngestDb(client: {
  from(table: string): {
    select(columns: string): {
      eq(column: string, value: string): {
        maybeSingle(): Promise<{ data: Record<string, unknown> | null; error: { message: string } | null }>;
      };
    };
    insert(row: Record<string, unknown>): {
      select(columns: string): {
        single(): Promise<{ data: Record<string, unknown> | null; error: { message: string } | null }>;
      };
    };
  };
}): BarcodeScanIngestDb {
  return {
    async findOrderById(orderId) {
      const { data, error } = await client
        .from("orders")
        .select("id, order_number")
        .eq("id", orderId)
        .maybeSingle();
      if (error) throw new Error(error.message);
      if (!data?.id || typeof data.order_number !== "string") return null;
      return { id: String(data.id), order_number: data.order_number };
    },

    async findScanByIdempotencyKey(key) {
      const { data, error } = await client
        .from("operational_scan_records")
        .select("id, idempotency_key")
        .eq("idempotency_key", key)
        .maybeSingle();
      if (error) throw new Error(error.message);
      if (!data?.id) return null;
      return {
        id: String(data.id),
        idempotency_key: typeof data.idempotency_key === "string" ? data.idempotency_key : null,
      };
    },

    async insertScan(row) {
      const { data, error } = await client
        .from("operational_scan_records")
        .insert({ ...row })
        .select("id")
        .single();
      if (error) throw new Error(error.message);
      if (!data?.id) throw new Error("Insert did not return scan id");
      return { id: String(data.id) };
    },
  };
}

/** CTN-SO carton barcode helpers aligned with Central SO numbering. */

export const SALES_ORDER_NUMBER_PATTERN = /^SO-\d{4}-\d{4,6}$/i;
export const CTN_SO_BARCODE_PATTERN = /^CTN-SO-\d{4}-\d{4,6}$/i;

export function normalizeBarcodeToken(value: string): string {
  return value.trim().toUpperCase().replace(/\s+/g, "");
}

export function isValidSalesOrderNumber(orderNumber: string): boolean {
  return SALES_ORDER_NUMBER_PATTERN.test(normalizeBarcodeToken(orderNumber));
}

export function isValidCtnSoBarcode(barcodeValue: string): boolean {
  return CTN_SO_BARCODE_PATTERN.test(normalizeBarcodeToken(barcodeValue));
}

/** CTN-SO barcode for an order number, e.g. SO-2026-000136 → CTN-SO-2026-000136 */
export function expectedCtnSoForOrderNumber(orderNumber: string): string {
  const normalizedOrder = normalizeBarcodeToken(orderNumber);
  if (!isValidSalesOrderNumber(normalizedOrder)) {
    return "";
  }
  return `CTN-${normalizedOrder}`;
}

export interface CtnSoValidationResult {
  ok: boolean;
  normalizedBarcode: string;
  normalizedExpected: string;
  normalizedOrderNumber: string;
  reason: string | null;
}

export function validateCtnSoBarcode(input: {
  barcodeValue: string;
  expectedBarcode: string;
  orderNumber: string;
}): CtnSoValidationResult {
  const normalizedBarcode = normalizeBarcodeToken(input.barcodeValue);
  const normalizedExpected = normalizeBarcodeToken(input.expectedBarcode);
  const normalizedOrderNumber = normalizeBarcodeToken(input.orderNumber);
  const derivedExpected = expectedCtnSoForOrderNumber(normalizedOrderNumber);

  if (!normalizedBarcode) {
    return fail(normalizedBarcode, normalizedExpected, normalizedOrderNumber, "barcode_value is required");
  }
  if (!normalizedOrderNumber) {
    return fail(normalizedBarcode, normalizedExpected, normalizedOrderNumber, "order_number is required");
  }
  if (!isValidSalesOrderNumber(normalizedOrderNumber)) {
    return fail(
      normalizedBarcode,
      normalizedExpected,
      normalizedOrderNumber,
      "order_number must match SO-YYYY-NNNN (4–6 digit sequence)",
    );
  }
  if (!isValidCtnSoBarcode(normalizedBarcode)) {
    return fail(
      normalizedBarcode,
      normalizedExpected,
      normalizedOrderNumber,
      "barcode_value must match CTN-SO-YYYY-NNNN pattern",
    );
  }
  if (!normalizedExpected) {
    return fail(normalizedBarcode, normalizedExpected, normalizedOrderNumber, "expected_barcode is required");
  }
  if (normalizedBarcode !== normalizedExpected) {
    return fail(
      normalizedBarcode,
      normalizedExpected,
      normalizedOrderNumber,
      "barcode_value must equal expected_barcode",
    );
  }
  if (normalizedExpected !== derivedExpected) {
    return fail(
      normalizedBarcode,
      normalizedExpected,
      normalizedOrderNumber,
      `expected_barcode must match order_number (${derivedExpected})`,
    );
  }

  return {
    ok: true,
    normalizedBarcode,
    normalizedExpected,
    normalizedOrderNumber,
    reason: null,
  };
}

function fail(
  normalizedBarcode: string,
  normalizedExpected: string,
  normalizedOrderNumber: string,
  reason: string,
): CtnSoValidationResult {
  return {
    ok: false,
    normalizedBarcode,
    normalizedExpected,
    normalizedOrderNumber,
    reason,
  };
}

/** Barcode App → Central scan ingest contract (HMAC-protected edge function). */

export const BARCODE_INGEST_SOURCE_APP = "barcode_app" as const;

export const BARCODE_INGEST_SCAN_TYPES = ["dispatch_gate", "carton"] as const;
export type BarcodeIngestScanType = (typeof BARCODE_INGEST_SCAN_TYPES)[number];

export const BARCODE_INGEST_VERIFICATION_TYPES = ["gate_check", "identity_match"] as const;
export type BarcodeIngestVerificationType = (typeof BARCODE_INGEST_VERIFICATION_TYPES)[number];

export const BARCODE_INGEST_VERIFICATION_STATUSES = ["verified"] as const;

export interface BarcodeScanPayload {
  source_app: typeof BARCODE_INGEST_SOURCE_APP;
  order_id: string;
  order_number: string;
  scan_type: BarcodeIngestScanType;
  verification_type: BarcodeIngestVerificationType;
  entity_type: "order";
  barcode_value: string;
  expected_barcode: string;
  verification_status: "verified";
  scan_source: string;
  barcode_app_reference?: string;
  submitted_at?: string;
}

export interface BarcodeScanIngestSuccessResponse {
  ok: true;
  scan_id: string;
  reference: string;
  message: string;
  duplicate?: false;
}

export interface BarcodeScanIngestDuplicateResponse {
  ok: true;
  duplicate: true;
  message: string;
}

export interface BarcodeScanIngestFailureResponse {
  ok: false;
  reason: string;
  message: string;
}

export type BarcodeScanIngestResponse =
  | BarcodeScanIngestSuccessResponse
  | BarcodeScanIngestDuplicateResponse
  | BarcodeScanIngestFailureResponse;

export interface BarcodeScanIngestHeaders {
  sourceApp: string;
  idempotencyKey: string;
  signature: string;
}

export const SCAN_TYPE_VERIFICATION_MAP: Record<
  BarcodeIngestScanType,
  BarcodeIngestVerificationType
> = {
  dispatch_gate: "gate_check",
  carton: "identity_match",
};
